    const bounds = widget.root.getBoundingClientRect();
    widget.moveTo(Math.max(8, Math.min(x, (window.innerWidth - bounds.width) / ratio - 8)), Math.max(8, Math.min(y, (window.innerHeight - bounds.height) / ratio - 8)));
